void worker(){signal(SIGTERM,term);signal(SIGINT,term);signal(SIGHUP,SIG_IGN);vector<Conn> cs;for(auto &e:cfg.eps)if(e.tls)for(int i:e.servers){SSL_CTX_set_tlsext_servername_callback(cfg.servers[i].ctx,sni);SSL_CTX_set_tlsext_servername_arg(cfg.servers[i].ctx,&e);}while(!stopped){vector<pollfd> ps;for(auto &e:cfg.eps)ps.push_back({e.fd,POLLIN,0});for(auto &c:cs){short ev=c.handshake?(POLLIN|POLLOUT):(!c.out.empty()?POLLOUT:POLLIN);ps.push_back({c.fd,ev,0});}poll(ps.data(),ps.size(),100);for(size_t k=0;k<cfg.eps.size();k++)if(ps[k].revents&POLLIN){int fd;while((fd=accept(cfg.eps[k].fd,nullptr,nullptr))>=0){fcntl(fd,F_SETFL,O_NONBLOCK);Conn c{fd,(int)k};if(cfg.eps[k].tls){c.ssl=SSL_new(cfg.servers[cfg.eps[k].def].ctx);SSL_set_fd(c.ssl,fd);SSL_set_accept_state(c.ssl);c.handshake=true;}cs.push_back(move(c));}}size_t old=ps.size()-cfg.eps.size();for(size_t i=0;i<old;i++){auto &c=cs[i];short ev=ps[cfg.eps.size()+i].revents;if(ev&(POLLERR|POLLHUP|POLLNVAL)){c.close=true;c.out.clear();continue;}if(c.handshake&&(ev&(POLLIN|POLLOUT))){int r=SSL_accept(c.ssl);if(r==1)c.handshake=false;else {int err=SSL_get_error(c.ssl,r);if(err!=SSL_ERROR_WANT_READ&&err!=SSL_ERROR_WANT_WRITE)c.close=true;}continue;}if((ev&POLLIN)&&c.out.empty()){char b[8192];int n=c.ssl?SSL_read(c.ssl,b,sizeof(b)):recv(c.fd,b,sizeof(b),0);if(n>0)c.in.append(b,n);else if(c.ssl){int err=SSL_get_error(c.ssl,n);if(err!=SSL_ERROR_WANT_READ&&err!=SSL_ERROR_WANT_WRITE)c.close=true;}else if(n==0||errno!=EAGAIN)c.close=true;}if(c.out.empty()&&!c.close){auto end=c.in.find("\r\n\r\n");if(end!=string::npos){string h=c.in.substr(0,end+4);c.in.erase(0,end+4);c.out=serve(c,h);c.sent=0;}else if(c.in.size()>(size_t)cfg.header){c.out=response(431,"",false,true);c.close=true;}}if((ev&POLLOUT)&&!c.out.empty()){int n=c.ssl?SSL_write(c.ssl,c.out.data()+c.sent,min<size_t>(c.out.size()-c.sent,16384)):send(c.fd,c.out.data()+c.sent,c.out.size()-c.sent,MSG_NOSIGNAL);if(n>0){c.sent+=n;if(c.sent==c.out.size()){c.out.clear();c.sent=0;}}else if(c.ssl){int err=SSL_get_error(c.ssl,n);if(err!=SSL_ERROR_WANT_READ&&err!=SSL_ERROR_WANT_WRITE){c.out.clear();c.close=true;}}else if(errno!=EAGAIN&&errno!=EWOULDBLOCK){c.out.clear();c.close=true;}}}for(size_t i=0;i<cs.size();)if(cs[i].close&&cs[i].out.empty()){if(cs[i].ssl){SSL_shutdown(cs[i].ssl);SSL_free(cs[i].ssl);}close(cs[i].fd);cs.erase(cs.begin()+i);}else i++;}for(auto &c:cs){if(c.ssl)SSL_free(c.ssl);close(c.fd);}_exit(0);}
int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);if(argc!=3||(string(argv[1])!="--config"&&string(argv[1])!="--check-config"))return 1;try{cfg=load(argv[2]);}catch(exception &e){cerr<<argv[2]<<": "<<e.what()<<"\n";return 1;}if(string(argv[1])=="--check-config")return 0;for(auto &e:cfg.eps){e.fd=socket(AF_INET,SOCK_STREAM,0);int one=1;setsockopt(e.fd,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));sockaddr_in a{};a.sin_family=AF_INET;a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);a.sin_port=htons(e.port);if(bind(e.fd,(sockaddr*)&a,sizeof(a))||listen(e.fd,1024)){perror("listen");return 1;}fcntl(e.fd,F_SETFL,O_NONBLOCK);}signal(SIGTERM,term);signal(SIGINT,term);signal(SIGHUP,SIG_IGN);vector<pid_t> children;auto spawn=[&](){pid_t p=fork();if(p==0)worker();if(p>0)children.push_back(p);};for(int i=0;i<cfg.workers;i++)spawn();while(!stopped){int status;pid_t p=waitpid(-1,&status,WNOHANG);if(p>0){children.erase(remove(children.begin(),children.end(),p),children.end());if(!stopped)spawn();}else usleep(50000);}for(auto p:children)kill(p,SIGTERM);for(auto p:children)waitpid(p,nullptr,0);return 0;}
